#!/bin/bash
set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1
test "$(id -un)" = sunyiq
task_root='/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/posthoc_clip_cpu_v1'
test ! -e "$task_root"
mkdir "$task_root"
mkdir "$task_root/logs"
python -B -X utf8 - <<'OWN_CLIP_DEPLOY_PY'
import base64,gzip,hashlib,json
from pathlib import Path
root=Path('/data1/home/sunyiq/us_nonnegative_repair_execution_20261010_001/posthoc_clip_cpu_v1')
assert root.resolve()==root and not root.is_symlink()
packed=base64.b64decode('',validate=True)
assert hashlib.sha256(packed).hexdigest()=='406cb3afa9a00366cb8a319d5c37f35fdf31f43e5e307a172a3dfb8a1adda6d7'
items=json.loads(gzip.decompress(packed))
assert len(items)==4 and {x['name'] for x in items}=={'frozen_scoring.py','SAVED_SIX_RESCORE_BINDINGS_v1.json','score_saved_clip.py','clip.sbatch'}
for item in items:
 raw=base64.b64decode(item['base64'],validate=True)
 assert len(raw)==item['bytes'] and hashlib.sha256(raw).hexdigest()==item['sha256']
 with (root/item['name']).open('xb') as f: f.write(raw)
print('OWN_CLIP_BOUND_FILES=4')
OWN_CLIP_DEPLOY_PY
test ! -e "$task_root/SUBMISSION_STARTED.txt"
printf 'ONE_CPU_POSTHOC_ANALYSIS_NO_TRAINING\n' > "$task_root/SUBMISSION_STARTED.txt"
set +e
task_submit_output=$(sbatch "$task_root/clip.sbatch" 2>&1)
task_submit_exit=$?
set -e
printf '%s\nOWN_CLIP_SUBMIT_EXIT=%s\n' "$task_submit_output" "$task_submit_exit"
printf '%s\n' "$task_submit_output" > "$task_root/SUBMISSION_OUTPUT.txt"
test "$task_submit_exit" -eq 0
if [[ "$task_submit_output" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
 task_job="${BASH_REMATCH[1]}"
else
 printf 'OWN_CLIP_SUBMISSION_ID_UNCERTAIN_NO_RETRY\n'
 exit 1
fi
printf '%s\n' "$task_job" > "$task_root/OWN_CLIP_JOB_ID.txt"
printf 'OWN_CLIP_SUBMITTED_JOB_ID=%s\n' "$task_job"
squeue -j "$task_job" -h -o '%i|%j|%T|%R' || true
printf 'OWN_CLIP_DEPLOY_DONE\n'
